package com.codearena.submission;
import com.codearena.common.domain.*; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="submissions",indexes={@Index(name="idx_submission_student_created",columnList="student_id,submitted_at"),@Index(name="idx_submission_problem",columnList="problem_id,submitted_at"),@Index(name="idx_submission_contest",columnList="contest_id,submitted_at"),@Index(name="idx_submission_status",columnList="status,submitted_at"),@Index(name="idx_submission_recent",columnList="submitted_at")}) public class Submission { @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @Column(name="student_id",nullable=false) public UUID studentId; @Column(name="problem_id",nullable=false) public UUID problemId; @Column(name="contest_id") public UUID contestId; @Column(nullable=false) public String language; @Column(name="source_code",nullable=false,columnDefinition="text") public String sourceCode; @Enumerated(EnumType.STRING) @Column(nullable=false) public SubmissionStatus status=SubmissionStatus.CREATED; @Enumerated(EnumType.STRING) @Column(nullable=false) public Verdict verdict=Verdict.PENDING; @Column(name="execution_time_ms") public Long executionTimeMs; @Column(name="memory_usage_kb") public Long memoryUsageKb; @Column(name="score",nullable=false) public Integer score=0; @Column(name="submitted_at",nullable=false) public Instant submittedAt=Instant.now(); @Column(name="completed_at") public Instant completedAt; @Version public long version; }
